-- D09: non-asset stock movement ledger + available quantity column.

CREATE TYPE "non_asset_stock_movement_type" AS ENUM (
  'initial_stock',
  'issue',
  'return',
  'replenishment',
  'write_off'
);

ALTER TABLE "non_asset_stock_items"
  ADD COLUMN "quantity_available" DECIMAL(18, 4);

UPDATE "non_asset_stock_items"
SET "quantity_available" = "quantity_on_hand"
WHERE "quantity_available" IS NULL;

ALTER TABLE "non_asset_stock_items"
  ALTER COLUMN "quantity_available" SET NOT NULL;

CREATE TABLE "non_asset_stock_movements" (
  "movement_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "stock_item_id" BIGINT NOT NULL,
  "movement_type" "non_asset_stock_movement_type" NOT NULL,
  "quantity" DECIMAL(18, 4) NOT NULL,
  "quantity_before" DECIMAL(18, 4),
  "quantity_after" DECIMAL(18, 4),
  "employee_id" BIGINT,
  "department" VARCHAR(128),
  "performed_by_user_id" BIGINT,
  "reference_reason" VARCHAR(255),
  "idempotency_key" VARCHAR(128),
  "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "non_asset_stock_movements_stock_item_id_fkey"
    FOREIGN KEY ("stock_item_id") REFERENCES "non_asset_stock_items"("stock_item_id")
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "non_asset_stock_movements_employee_id_fkey"
    FOREIGN KEY ("employee_id") REFERENCES "employees"("employee_id")
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "non_asset_stock_movements_performed_by_user_id_fkey"
    FOREIGN KEY ("performed_by_user_id") REFERENCES "users"("user_id")
    ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE UNIQUE INDEX "non_asset_stock_movements_idempotency_key_key"
  ON "non_asset_stock_movements"("idempotency_key")
  WHERE "idempotency_key" IS NOT NULL;

CREATE INDEX "non_asset_stock_movements_stock_item_id_created_at_idx"
  ON "non_asset_stock_movements"("stock_item_id", "created_at");

CREATE INDEX "non_asset_stock_movements_employee_id_idx"
  ON "non_asset_stock_movements"("employee_id");

CREATE INDEX "non_asset_stock_movements_movement_type_idx"
  ON "non_asset_stock_movements"("movement_type");

-- Idempotent opening balance for legacy rows (no movements yet).
INSERT INTO "non_asset_stock_movements" (
  "stock_item_id",
  "movement_type",
  "quantity",
  "quantity_before",
  "quantity_after",
  "reference_reason"
)
SELECT
  s."stock_item_id",
  'initial_stock'::"non_asset_stock_movement_type",
  s."quantity_on_hand",
  0,
  s."quantity_on_hand",
  'Migrated opening balance'
FROM "non_asset_stock_items" s
WHERE NOT EXISTS (
  SELECT 1 FROM "non_asset_stock_movements" m WHERE m."stock_item_id" = s."stock_item_id"
);
